from Backend.Platform10.contracts.dtos import (
    MarketStateDTO, MethodologyResultDTO, ICTProfileDTO,
    EvidenceDTO, ExplainabilityDTO, ExecutionContext
)
from Backend.Platform9.contracts.dtos import (
    FairValueGapConcept, OrderBlockConcept, LiquiditySweepConcept, MarketStructureShiftConcept
)

class ICTCore:
    __version__ = "v1.0"
    __dto_version__ = "v1.0"
    __schema_version__ = "v1.0"
    
    def execute(self, state: MarketStateDTO) -> MethodologyResultDTO:
        # Extract Concepts generated by Platform 9
        # The Methodology does NOT detect raw geometry; it synthesizes concepts.
        concepts = state.concepts.concepts
        
        # Mock logic
        has_fvg = any(isinstance(c, FairValueGapConcept) for c in concepts.values())
        has_ob = any(isinstance(c, OrderBlockConcept) for c in concepts.values())
        has_mss = any(isinstance(c, MarketStructureShiftConcept) for c in concepts.values())
        has_sweep = any(isinstance(c, LiquiditySweepConcept) for c in concepts.values())
        
        score = 0.0
        if has_fvg: score += 0.4
        if has_ob: score += 0.3
        if has_sweep and has_mss: score += 0.3
        
        bias = "Bullish" if score > 0.5 else "Neutral"
        
        profile = ICTProfileDTO(
            methodology_id="p10_ict",
            version=self.__version__,
            health="HEALTHY",
            confidence=score,
            reliability=0.85,
            applicability=1.0,
            provenance=[],
            evidence=EvidenceDTO(supporting_concepts=[], conflicting_concepts=[], raw_evidence=[]),
            explainability=ExplainabilityDTO("", "", "", "", "", ""),
            execution_id=state.context.run_id,
            execution_timestamp=state.context.timestamp,
            scheduler_cadence="TICK",
            cache_status="MISS",
            validation_status="VALID",
            institutional_bias=bias,
            liquidity_target="BSL",
            displacement_strength="Strong",
            market_structure_state="Expansion",
            killzone_alignment=True,
            time_of_day_context="NY_AM"
        )
        
        return MethodologyResultDTO(
            methodology_id="p10_ict",
            version=self.__version__,
            plugin_id="ICTCore",
            execution_id=state.context.run_id,
            execution_context=state.context,
            score=score,
            confidence=score,
            strength=score,
            evidence=profile.evidence,
            supporting_concepts=[],
            conflicting_concepts=[],
            preconditions=[],
            failure_reasons=[],
            explainability=profile.explainability,
            metadata={"profile": profile},
            execution_duration_ms=15.0,
            validation_status="VALID"
        )